import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import { HallEvents } from '../HallEvents';

export class MonthClockSystem implements System {

    private _acc = 0;
    private readonly _secondsPerMonth = 60;

    onTick(world: World, dt: number): void {
        this._acc += dt;
        while (this._acc >= this._secondsPerMonth) {
            this._acc -= this._secondsPerMonth;
            world.bus.emit(HallEvents.MONTH_PASSED);
        }
    }
}